def transform(grid):
    # The separator lattice has 3-row by 6-column pitch. Each reduced
    # pixel is the marked color at the intersection of a horizontal and
    # vertical separator; unmarked intersections become the tile color 7.
    out = []
    for r in (0, 3, 6, 9, 12, 15, 18):
        row = []
        for c in (2, 8, 14, 20, 26):
            if r < len(grid) and c < len(grid[0]):
                v = grid[r][c]
                row.append(7 if v == 4 else v)
        if row:
            out.append(row)
    return out[:4]
